INSERT INTO "products" ("id", "slug", "name", "brand", "category", "tagline", "description", "isNew", "position", "isActive", "createdAt", "updatedAt") VALUES
  ('cmtl831s10004wmhwglw7a6xv', 'iphone-17-pro', 'iPhone 17 Pro', 'Apple', 'Smartphones', 'Aerospace-grade aluminium unibody with a vapour chamber.', 'A19 Pro silicon, a 48MP Fusion triple camera and the brightest Super Retina XDR display Apple has shipped. Buy it against your mutual fund holdings and stay invested while you pay.', TRUE, 0, TRUE, '2026-09-03T07:47:46.753Z', '2026-09-03T07:47:46.753Z'),
  ('cmtl849ny001nwmhwekjr5izl', 'samsung-galaxy-s25-ultra', 'Galaxy S25 Ultra', 'Samsung', 'Smartphones', 'Titanium frame, built-in S Pen and a 200MP main sensor.', 'Snapdragon 8 Elite for Galaxy, a 6.9-inch Dynamic AMOLED 2X panel and Galaxy AI throughout One UI. Financed against your portfolio, not your salary slip.', TRUE, 1, TRUE, '2026-09-03T07:48:43.630Z', '2026-09-03T07:48:43.630Z'),
  ('cmtl85gfq0036wmhw7nh2rfgb', 'google-pixel-10-pro', 'Pixel 10 Pro', 'Google', 'Smartphones', 'Tensor G5 with seven years of OS and security updates.', 'Google''s computational photography stack on a Super Actua display, with Gemini Nano running on-device. Pick a tenure, keep your SIP running.', FALSE, 2, TRUE, '2026-09-03T07:49:39.063Z', '2026-09-03T07:49:39.063Z'),
  ('cmtl86n0x004pwmhwzdyyvacn', 'oneplus-13', 'OnePlus 13', 'OnePlus', 'Smartphones', '6000mAh silicon-carbon battery with 100W SuperVOOC.', 'Snapdragon 8 Elite, a 2K ProXDR display and Hasselblad-tuned optics. A flagship that charges in half an hour and repays over five years if you want it to.', FALSE, 3, TRUE, '2026-09-03T07:50:34.257Z', '2026-09-03T07:50:34.257Z'),
  ('cmtl87khl005wwmhwmtqupx2l', 'nothing-phone-3', 'Nothing Phone (3)', 'Nothing', 'Smartphones', 'Glyph Matrix interface on a transparent rear panel.', 'Nothing OS 3.0 on Snapdragon 8s Gen 4, with a rear Glyph Matrix that turns notifications into light. The most affordable way onto a 1Fi EMI plan.', TRUE, 4, TRUE, '2026-09-03T07:51:17.626Z', '2026-09-03T07:51:17.626Z')
